  const SKIN_CARD_ORDER = ["mist", "ivory", "rose", "abyss", "aurora", "nebula", "ember", "midnight"];
  function skinsInCardOrder() {
    const byId2 = new Map(SKINS.map((skin) => [skin.id, skin]));
    const listed = new Set(SKIN_CARD_ORDER);
    const ordered = SKIN_CARD_ORDER.map((id) => byId2.get(id)).filter(Boolean);
    return ordered.concat(SKINS.filter((skin) => !listed.has(skin.id)));
  }
