var theme_default = '/* Only installed while this embedded ring owns the model slot. The body\n   portals inherit the same native tokens as the composer and every preset. */\n.sjrr, .sjrr-panel, .sjrr-dropdown, .sjrr-modal, .sjrr-toast {\n  --sjrr-opaque-base: #232428;\n  --sjrr-bg: var(--wd-palette-ring-background, var(--dsh-dream-skin-composer-base, var(--dsw-alias-bg-layer-1, #232428)));\n  --sjrr-fg: var(--wd-palette-ring-text, var(--dsw-alias-label-primary, #f3f4f6));\n  --sjrr-secondary: color-mix(in srgb, var(--sjrr-fg) 72%, var(--sjrr-bg));\n  --sjrr-track: var(--wd-palette-ring-track, var(--dsw-alias-bg-overlay, #363940));\n  --sjrr-border: var(--dsw-alias-border-l3, rgba(150,154,167,.23));\n  --sjrr-accent: var(--wd-palette-ring-accent, var(--dsw-alias-state-business-primary, #94bfff));\n  --sjrr-focus: var(--sjrr-accent);\n}\n@supports (color: light-dark(white, black)) {\n  .sjrr, .sjrr-panel, .sjrr-dropdown, .sjrr-modal, .sjrr-toast {\n    --sjrr-opaque-base: light-dark(#f8f9fc, #232428);\n  }\n}\n/* A solid base is a separate paint layer. Even an alpha-bearing host token\n   cannot make text, whale glyphs or bubbles show through the ring or menus. */\n.sjrr-dial::before, .sjrr-inner, .sjrr-dropdown, .sjrr-status, .sjrr-toast {\n  background-color: var(--sjrr-opaque-base);\n  background-image: linear-gradient(var(--sjrr-bg), var(--sjrr-bg));\n}\n.sjrr-inner {\n  background-image: linear-gradient(180deg, rgba(255,255,255,.035), rgba(255,255,255,0) 72%), linear-gradient(var(--sjrr-bg), var(--sjrr-bg));\n}\n/* Native DSH Modal/SettingsRoot use z=1000. Ring and menu stay above the\n   composer (z=9) but below those modal surfaces, independently of chat scroll. */\n.sjrr-panel { z-index: 900; }\n.sjrr-dropdown { z-index: 950; }\nhtml body .sjrr-modal[aria-modal="true"] {\n  background-color: var(--sjrr-opaque-base) !important;\n  background-image: linear-gradient(var(--sjrr-bg), var(--sjrr-bg)) !important;\n}\n.sjrr-switch-track { background: var(--sjrr-track); border: 1px solid var(--sjrr-border); }\n.sjrr-switch-thumb { background: var(--sjrr-secondary); left: 1px; top: 1px; }\n.sjrr-switch[aria-checked="true"] .sjrr-switch-track { background: var(--sjrr-accent); border-color: var(--sjrr-accent); }\n.sjrr-switch[aria-checked="true"] .sjrr-switch-thumb { background: var(--dsw-alias-label-primary-foreground, white); }\n.sjrr-trigger-value, .sjrr-effort-label { color: var(--sjrr-fg) !important; }\n.sjrr-status:not([data-busy="true"]), .sjrr-picker-error, .sjrr-modal .sjrr-modal-error { color: var(--dsw-alias-state-error-primary, #fda4af); }\n.sjrr-settings input { accent-color: var(--sjrr-accent, var(--dsw-alias-state-business-primary, #94bfff)); }\n.sjrr-model-list { scrollbar-color: var(--sjrr-secondary) transparent; }\n.sjrr-model-option[data-highlighted="true"], .sjrr-model-option:hover,\n.sjrr-model:hover, .sjrr-model[aria-expanded="true"] { background: var(--dsw-alias-interactive-bg-hover, rgba(148,163,184,.09)); }\n.sjrr-modal-button[data-primary="true"] {\n  color: var(--dsw-alias-label-primary-foreground, #fff);\n  background: var(--sjrr-accent); border-color: var(--sjrr-accent);\n}\n';

